-- Mars Collection SQLite to MySQL/MariaDB export for cPanel phpMyAdmin.
-- Import into an EMPTY database selected in phpMyAdmin. This file does not DROP tables.
-- Then set Laravel DB_CONNECTION=mysql and the cPanel DB credentials in .env.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

-- Table: migrations
CREATE TABLE `migrations` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `migration` VARCHAR(255) not null, `batch` integer not null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: users
CREATE TABLE `users` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `name` VARCHAR(255) not null, `email` VARCHAR(255) not null, `email_verified_at` datetime, `password` VARCHAR(255) not null, `remember_token` VARCHAR(255), `created_at` datetime, `updated_at` datetime, `is_admin` tinyint(1) not null default '0') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: password_reset_tokens
CREATE TABLE `password_reset_tokens` (`email` VARCHAR(255) not null, `token` VARCHAR(255) not null, `created_at` datetime, primary key (`email`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: sessions
CREATE TABLE `sessions` (`id` VARCHAR(255) not null, `user_id` integer, `ip_address` VARCHAR(255), `user_agent` text, `payload` text not null, `last_activity` integer not null, primary key (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: cache
CREATE TABLE `cache` (`key` VARCHAR(255) not null, `value` text not null, `expiration` integer not null, primary key (`key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: cache_locks
CREATE TABLE `cache_locks` (`key` VARCHAR(255) not null, `owner` VARCHAR(255) not null, `expiration` integer not null, primary key (`key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: jobs
CREATE TABLE `jobs` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `queue` VARCHAR(255) not null, `payload` text not null, `attempts` integer not null, `reserved_at` integer, `available_at` integer not null, `created_at` integer not null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: job_batches
CREATE TABLE `job_batches` (`id` VARCHAR(255) not null, `name` VARCHAR(255) not null, `total_jobs` integer not null, `pending_jobs` integer not null, `failed_jobs` integer not null, `failed_job_ids` text not null, `options` text, `cancelled_at` integer, `created_at` integer not null, `finished_at` integer, primary key (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: failed_jobs
CREATE TABLE `failed_jobs` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `uuid` VARCHAR(255) not null, `connection` text not null, `queue` text not null, `payload` text not null, `exception` text not null, `failed_at` datetime not null default CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: categories
CREATE TABLE `categories` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `name` VARCHAR(255) not null, `slug` VARCHAR(255) not null, `description` text, `image` VARCHAR(255), `is_active` tinyint(1) not null default '1', `created_at` datetime, `updated_at` datetime, `sort_order` integer not null default '0') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: brands
CREATE TABLE `brands` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `name` VARCHAR(255) not null, `slug` VARCHAR(255) not null, `description` text, `logo` VARCHAR(255), `website` VARCHAR(255), `is_active` tinyint(1) not null default '1', `created_at` datetime, `updated_at` datetime) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: orders
CREATE TABLE `orders` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `order_number` VARCHAR(255) not null, `user_id` integer, `customer_name` VARCHAR(255) not null, `customer_email` VARCHAR(255) not null, `customer_phone` VARCHAR(255), `shipping_address` text not null, `billing_address` text not null, `subtotal` DECIMAL(12,2) not null, `tax` DECIMAL(12,2) not null default '0', `shipping_cost` DECIMAL(12,2) not null default '0', `total` DECIMAL(12,2) not null, `status` VARCHAR(255)  not null default 'pending', `payment_method` VARCHAR(255) not null default 'cash_on_delivery', `notes` text, `created_at` datetime, `updated_at` datetime, foreign key(`user_id`) references `users`(`id`) on delete set null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: bundles
CREATE TABLE `bundles` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `name` VARCHAR(255) not null, `description` text not null, `price` DECIMAL(12,2) not null, `original_price` DECIMAL(12,2), `image` VARCHAR(255) not null, `badge` VARCHAR(255), `badge_color` VARCHAR(255), `is_featured` tinyint(1) not null default '0', `is_trending` tinyint(1) not null default '0', `sold_count` integer not null default '0', `rating` DECIMAL(12,2) not null default '4.5', `review_count` integer not null default '0', `category` VARCHAR(255) not null, `is_active` tinyint(1) not null default '1', `created_at` datetime, `updated_at` datetime, `slug` VARCHAR(255)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: products
CREATE TABLE `products` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `name` VARCHAR(255) not null, `slug` VARCHAR(255) not null, `description` text, `price` DECIMAL(12,2) not null, `original_price` DECIMAL(12,2), `category_id` integer not null, `brand_id` integer not null, `image` VARCHAR(255), `rating` DECIMAL(12,2) not null DEFAULT 0, `sold_count` integer not null DEFAULT 0, `badge` VARCHAR(255), `badge_color` VARCHAR(255), `is_featured` tinyint(1) not null DEFAULT 0, `is_trending` tinyint(1) not null DEFAULT 0, `stock_quantity` integer not null DEFAULT 0, `sku` VARCHAR(255), `created_at` datetime, `updated_at` datetime, `is_active` tinyint(1) not null DEFAULT 1, `reviews_count` integer not null DEFAULT 0, `colors` text, `extra_images` text, `variants` text, `meta_description` text, `variant_images` text, foreign key(`brand_id`) references brands(`id`) on delete cascade on update no action, foreign key(`category_id`) references categories(`id`) on delete cascade on update no action) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: bundle_items
CREATE TABLE `bundle_items` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `bundle_id` integer not null, `product_id` integer not null, `quantity` integer not null default '1', `created_at` datetime, `updated_at` datetime, foreign key(`bundle_id`) references `bundles`(`id`) on delete cascade, foreign key(`product_id`) references `products`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: carts
CREATE TABLE `carts` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `user_id` integer, `session_id` VARCHAR(255), `product_id` integer, `quantity` integer not null DEFAULT 1, `created_at` datetime, `updated_at` datetime, `bundle_id` integer, `selected_color` VARCHAR(255), `selected_size` VARCHAR(255), foreign key(`bundle_id`) references bundles(`id`) on delete cascade on update no action, foreign key(`user_id`) references users(`id`) on delete cascade on update no action, foreign key(`product_id`) references products(`id`) on delete cascade on update no action) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: order_items
CREATE TABLE `order_items` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `order_id` integer not null, `product_id` integer, `product_name` VARCHAR(255), `product_price` DECIMAL(12,2), `quantity` integer not null, `subtotal` DECIMAL(12,2) not null, `created_at` datetime, `updated_at` datetime, `bundle_id` integer, `bundle_name` VARCHAR(255), `bundle_price` DECIMAL(12,2), `selected_color` VARCHAR(255), `selected_size` VARCHAR(255), foreign key(`bundle_id`) references bundles(`id`) on delete cascade on update no action, foreign key(`order_id`) references orders(`id`) on delete cascade on update no action, foreign key(`product_id`) references products(`id`) on delete cascade on update no action) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: appointments
CREATE TABLE `appointments` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `customer_name` VARCHAR(255) not null, `customer_email` VARCHAR(255) not null, `customer_phone` VARCHAR(255) not null, `service_type` VARCHAR(255) not null, `service_description` text, `appointment_date` date not null, `appointment_time` time not null, `duration` integer not null default '60', `price` DECIMAL(12,2) not null, `special_requests` text, `status` VARCHAR(255)  not null default 'pending', `notes` text, `created_at` datetime, `updated_at` datetime) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: services
CREATE TABLE `services` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `name` VARCHAR(255) not null, `slug` VARCHAR(255) not null, `description` text not null, `price` DECIMAL(12,2) not null, `duration` integer not null default '60', `is_active` tinyint(1) not null default '1', `sort_order` integer not null default '0', `created_at` datetime, `updated_at` datetime) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: settings
CREATE TABLE `settings` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `key` VARCHAR(255) not null, `value` text not null, `type` VARCHAR(255) not null default 'string', `group` VARCHAR(255) not null default 'general', `label` VARCHAR(255) not null, `description` text, `created_at` datetime, `updated_at` datetime) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: booking_settings
CREATE TABLE `booking_settings` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `day_of_week` integer not null, `is_disabled` tinyint(1) not null default '0', `disabled_hours` text, `business_hours_start` time, `business_hours_end` time, `slot_duration` integer not null default '60', `break_start` time, `break_end` time, `created_at` datetime, `updated_at` datetime) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: review_links
CREATE TABLE `review_links` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `order_id` integer not null, `unique_token` VARCHAR(255) not null, `email` VARCHAR(255) not null, `is_used` tinyint(1) not null default '0', `expires_at` datetime, `created_at` datetime, `updated_at` datetime, foreign key(`order_id`) references `orders`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: reviews
CREATE TABLE `reviews` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `order_id` integer not null, `user_id` integer, `product_id` integer, `bundle_id` integer, `rating` integer not null, `comment` text, `is_approved` tinyint(1) not null DEFAULT 0, `created_at` datetime, `updated_at` datetime, foreign key(`bundle_id`) references bundles(`id`) on delete cascade on update no action, foreign key(`product_id`) references products(`id`) on delete cascade on update no action, foreign key(`user_id`) references users(`id`) on delete cascade on update no action, foreign key(`order_id`) references orders(`id`) on delete cascade on update no action) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: contacts
CREATE TABLE `contacts` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `first_name` VARCHAR(255) not null, `last_name` VARCHAR(255) not null, `email` VARCHAR(255) not null, `phone` VARCHAR(255), `subject` VARCHAR(255) not null, `message` text not null, `ip_address` VARCHAR(255), `user_agent` VARCHAR(255), `is_bot` tinyint(1) not null default '0', `website` VARCHAR(255), `company` VARCHAR(255), `created_at` datetime, `updated_at` datetime) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: newsletter_subscribers
CREATE TABLE `newsletter_subscribers` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `email` VARCHAR(255) not null, `ip_address` VARCHAR(255), `user_agent` VARCHAR(255), `source` VARCHAR(255) not null default 'website', `is_active` tinyint(1) not null default '1', `subscribed_at` datetime, `unsubscribed_at` datetime, `created_at` datetime, `updated_at` datetime) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: product_embeddings
CREATE TABLE `product_embeddings` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `product_id` integer not null, `embedding` text not null, `model` VARCHAR(255) not null default 'gemini-embedding-004', `created_at` datetime, `updated_at` datetime, foreign key(`product_id`) references `products`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: traffic_visits
CREATE TABLE `traffic_visits` (`id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY, `visitor_key` VARCHAR(255) not null, `path` VARCHAR(255) not null, `visited_at` datetime not null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE UNIQUE INDEX `booking_settings_day_of_week_unique` on `booking_settings` (`day_of_week`);
CREATE UNIQUE INDEX `brands_slug_unique` on `brands` (`slug`);
CREATE UNIQUE INDEX `bundles_slug_unique` on `bundles` (`slug`);
CREATE UNIQUE INDEX `categories_slug_unique` on `categories` (`slug`);
CREATE UNIQUE INDEX `failed_jobs_uuid_unique` on `failed_jobs` (`uuid`);
CREATE INDEX `jobs_queue_index` on `jobs` (`queue`);
CREATE UNIQUE INDEX `newsletter_subscribers_email_unique` on `newsletter_subscribers` (`email`);
CREATE UNIQUE INDEX `orders_order_number_unique` on `orders` (`order_number`);
CREATE UNIQUE INDEX `product_embeddings_product_id_unique` on `product_embeddings` (`product_id`);
CREATE UNIQUE INDEX `products_sku_unique` on `products` (`sku`);
CREATE UNIQUE INDEX `products_slug_unique` on `products` (`slug`);
CREATE UNIQUE INDEX `review_links_unique_token_unique` on `review_links` (`unique_token`);
CREATE UNIQUE INDEX `services_slug_unique` on `services` (`slug`);
CREATE INDEX `sessions_last_activity_index` on `sessions` (`last_activity`);
CREATE INDEX `sessions_user_id_index` on `sessions` (`user_id`);
CREATE UNIQUE INDEX `settings_key_unique` on `settings` (`key`);
CREATE INDEX `traffic_visits_visited_at_index` on `traffic_visits` (`visited_at`);
CREATE INDEX `traffic_visits_visitor_key_index` on `traffic_visits` (`visitor_key`);
CREATE UNIQUE INDEX `unique_bundle_review` on `reviews` (`order_id`, `user_id`, `bundle_id`);
CREATE UNIQUE INDEX `unique_product_review` on `reviews` (`order_id`, `user_id`, `product_id`);
CREATE UNIQUE INDEX `users_email_unique` on `users` (`email`);

-- Data from the local SQLite database














SET FOREIGN_KEY_CHECKS=1;
